"""E2E: the remote-access password is generated by install.sh's helper,
stored as typed in ``config.json``, kept across installs, and checked in
constant time.

* ``python -m kiss.core.remote_password`` (what ``install.sh`` runs)
  prints a fresh 20-character alphanumeric password when none is stored
  and ``config.json`` under ``KISS_HOME`` holds exactly that value under
  ``remote_password``; a second run (an update) prints the same password
  and leaves the file alone, keeping every other setting; a run with
  ``--rotate`` draws a new one; an emptied key draws a new one too.
* ``password_accepted`` accepts the stored password and rejects any
  other, including the empty one; with no password stored only the
  empty password passes.
* The retired hash-only key of an earlier release is purged on the
  next save (``RETIRED_KEYS``).
"""

from __future__ import annotations

import json
import os
import subprocess
import sys
import tempfile
from pathlib import Path

import pytest

from kiss.core import user_config
from kiss.core.remote_password import (
    PASSWORD_LENGTH,
    ensure_password,
    generate_password,
    password_accepted,
)


def _run_module_raw(home: Path, *args: str) -> subprocess.CompletedProcess[str]:
    env = {**os.environ, "KISS_HOME": str(home)}
    return subprocess.run(
        [sys.executable, "-m", "kiss.core.remote_password", *args],
        capture_output=True, text=True, env=env, timeout=120, check=False,
    )


def _run_module(home: Path, *args: str) -> str:
    done = _run_module_raw(home, *args)
    assert done.returncode == 0, done.stderr
    return done.stdout.strip()


def test_install_prints_the_password_it_stored_and_later_installs_keep_it() -> None:
    home = Path(tempfile.mkdtemp())
    config = home / "config.json"
    config.write_text(json.dumps({"max_budget": 42}))

    # ``--show`` never stores one: nothing yet.
    assert _run_module(home, "--show") == ""
    assert "remote_password" not in json.loads(config.read_text())

    printed = _run_module(home)

    assert len(printed) == PASSWORD_LENGTH
    assert printed.isalnum()
    stored = json.loads(config.read_text())
    assert stored["remote_password"] == printed
    assert stored["max_budget"] == 42
    assert password_accepted(printed, stored["remote_password"])
    assert not password_accepted(printed + "x", stored["remote_password"])
    assert not password_accepted("", stored["remote_password"])
    if os.name == "posix":
        assert config.stat().st_mode & 0o077 == 0

    # An update re-runs the module: the password the user's devices know
    # stays, and the file is not rewritten.
    before = config.stat().st_mtime_ns
    assert _run_module(home) == printed
    assert _run_module(home, "--show") == printed
    assert json.loads(config.read_text())["remote_password"] == printed
    assert config.stat().st_mtime_ns == before
    # install.sh reads the stored password through the module, so a
    # compact (hand-written) config.json is read like any other.
    config.write_text(json.dumps({"remote_password": printed, "max_budget": 42}))
    assert _run_module(home, "--show") == printed
    assert _run_module(home) == printed

    # A deliberate rotation draws a new one; the old one stops working.
    rotated = _run_module(home, "--rotate")
    assert rotated != printed
    assert len(rotated) == PASSWORD_LENGTH
    stored = json.loads(config.read_text())
    assert stored["remote_password"] == rotated
    assert stored["max_budget"] == 42
    assert not password_accepted(printed, stored["remote_password"])
    assert _run_module(home) == rotated

    # A key cleared by hand gets a fresh password on the next install.
    config.write_text(json.dumps({"remote_password": "", "max_budget": 7}))
    refilled = _run_module(home)
    assert refilled not in ("", printed, rotated)
    assert json.loads(config.read_text()) == {"remote_password": refilled, "max_budget": 7}


@pytest.mark.skipif(
    os.name != "posix" or os.geteuid() == 0, reason="needs a file mode root cannot bypass",
)
def test_an_unreadable_config_is_left_alone() -> None:
    # A config.json that exists but cannot be read must not be replaced
    # by one holding only a fresh password: the module fails instead
    # (install.sh then warns and carries on) and the file is untouched.
    home = Path(tempfile.mkdtemp())
    config = home / "config.json"
    config.write_text(json.dumps({"remote_password": "hidden", "max_budget": 5}))
    config.chmod(0)
    try:
        for args in ((), ("--rotate",), ("--show",)):
            done = _run_module_raw(home, *args)
            assert done.returncode != 0, args
            assert "cannot be read" in done.stderr, done.stderr
            assert done.stdout == ""
    finally:
        config.chmod(0o600)
    assert json.loads(config.read_text()) == {"remote_password": "hidden", "max_budget": 5}


def test_generate_and_accept() -> None:
    pw = generate_password()
    assert len(pw) == PASSWORD_LENGTH
    assert pw.isalnum()
    assert pw != generate_password()
    assert password_accepted(pw, pw)
    assert not password_accepted(pw.lower(), pw) or pw == pw.lower()
    assert not password_accepted("", pw)
    # No password configured: only the empty password passes.
    assert password_accepted("", "")
    assert not password_accepted("anything", "")


def test_ensure_password_purges_the_retired_hash_key(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch,
) -> None:
    config = tmp_path / "config.json"
    config.write_text(json.dumps({"remote_password_hash": "sha256$s$d", "max_budget": 3}))
    monkeypatch.setitem(vars(user_config), "CONFIG_DIR", tmp_path)

    pw = ensure_password()

    stored = json.loads(config.read_text())
    assert stored["remote_password"] == pw
    assert "remote_password_hash" not in stored
    assert stored["max_budget"] == 3
    assert "remote_password" not in user_config.RETIRED_KEYS
    # A junk-typed stored value counts as no password: a fresh one is drawn.
    config.write_text(json.dumps({"remote_password": 12345}))
    assert ensure_password() != pw
    assert ensure_password() == json.loads(config.read_text())["remote_password"]
